from unittest import mock

from app.weather import current_temp


@mock.patch("requests.get")
def test_current_temp(mock_get):
    mock_get.return_value.json.return_value = {"temp": 21.5}
    assert current_temp("Tokyo") == 21.5
    mock_get.assert_called_once_with(
        "https://api.example.com/weather", params={"q": "Tokyo"}, timeout=5
    )

import pytest
import requests

from app import weather


class FakeResponse:
    def __init__(self, payload, status=200):
        self.payload = payload
        self.status = status

    def raise_for_status(self):
        if self.status >= 400:
            raise requests.HTTPError(f"{self.status} error")

    def json(self):
        return self.payload


def test_current_temp(monkeypatch):
    calls = []

    def fake_get(url, **kwargs):
        calls.append((url, kwargs))
        return FakeResponse({"temp": 21.5})

    monkeypatch.setattr(weather, "get", fake_get)
    assert weather.current_temp("Tokyo") == 21.5
    assert calls == [(weather.API_URL, {"params": {"q": "Tokyo"}, "timeout": 5})]


def test_current_temp_raises_on_error(monkeypatch):
    monkeypatch.setattr(weather, "get", lambda url, **kwargs: FakeResponse({}, 503))
    with pytest.raises(requests.HTTPError):
        weather.current_temp("Tokyo")
